const ArticlesComponent={render:(content,layout,colorMode,pStyle,lang)=>{const items=SectionUtils.lines(content);if(!items.length)return'';const t=SectionUtils.theme(colorMode,pStyle);const title=lang==='th'?'บทความ / สื่อเผยแพร่':'Articles / Publications';const body=items.map(l=>{const [name,desc,url]=SectionUtils.parts(l);return `<div class="extra-card compact"><h4>${url?`<a href="${url}" target="_blank" rel="noopener noreferrer">${name||''}</a>`:name||''}</h4>${desc?`<p>${desc}</p>`:''}</div>`}).join('');return SectionUtils.wrap(SectionUtils.title(title,t)+`<div class="extra-grid">${body}</div>`,'articles-section')}};
